page Sim "/" {
  ref box
  ref balls
  ref raf
  ref running
  state n = 5
  state frames = 0
  state paused = false

  fn make() {
    return {
      x: 10 + Math.random() * 380,
      y: 10 + Math.random() * 280,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6
    }
  }

  fn clamp(b) {
    if b.x < 10 { b.x = 10; b.vx = Math.abs(b.vx) }
    if b.x > 390 { b.x = 390; b.vx = -Math.abs(b.vx) }
    if b.y < 10 { b.y = 10; b.vy = Math.abs(b.vy) }
    if b.y > 290 { b.y = 290; b.vy = -Math.abs(b.vy) }
  }

  fn step() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      clamp(b)
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let dist = Math.sqrt(dx * dx + dy * dy)
        if dist < 20 {
          if dist == 0 { dx = 1; dy = 0; dist = 1 }
          let nx = dx / dist
          let ny = dy / dist
          let push = (20 - dist) / 2
          a.x -= nx * push
          a.y -= ny * push
          c.x += nx * push
          c.y += ny * push
          let tvx = a.vx
          let tvy = a.vy
          a.vx = c.vx
          a.vy = c.vy
          c.vx = tvx
          c.vy = tvy
          clamp(a)
          clamp(c)
        }
      }
    }
  }

  fn draw() {
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#3b82f6"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, 10, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    if !running { return }
    step()
    draw()
    frames++
    raf = requestAnimationFrame(loop)
  }

  fn reset() {
    balls = Array.from({ length: 5 }, () => make())
    n = 5
    frames = 0
    draw()
  }

  fn add() {
    balls.push(make())
    n = balls.length
  }

  fn toggle() {
    paused = !paused
    running = !paused
    if running {
      raf = requestAnimationFrame(loop)
    } else {
      cancelAnimationFrame(raf)
    }
  }

  mount {
    running = true
    reset()
    raf = requestAnimationFrame(loop)
    cleanup {
      running = false
      cancelAnimationFrame(raf)
    }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" primary -> add()
      button `${paused ? "Reanudar" : "Pausar"}` -> toggle()
      button "Reiniciar" danger -> reset()
    }
    text `Pelotas: ${n}`
    text `Cuadros: ${frames}`
  }
}

page Simulacion "/" {
  state count = 5
  state frames = 0
  state paused = false
  ref box
  ref ctx
  ref balls
  ref raf

  fn makeBall() {
    return {
      x: 10 + Math.random() * 380,
      y: 10 + Math.random() * 280,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      r: 10
    }
  }

  fn makeBalls(n) {
    let list = []
    for (let i = 0; i < n; i++) {
      list.push(makeBall())
    }
    return list
  }

  fn step() {
    let list = balls
    for (let i = 0; i < list.length; i++) {
      let b = list[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx) }
      if (b.x > 400 - b.r) { b.x = 400 - b.r; b.vx = -Math.abs(b.vx) }
      if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy) }
      if (b.y > 300 - b.r) { b.y = 300 - b.r; b.vy = -Math.abs(b.vy) }
    }
    for (let i = 0; i < list.length; i++) {
      for (let j = i + 1; j < list.length; j++) {
        let a = list[i]
        let c = list[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let dist = Math.sqrt(dx * dx + dy * dy)
        let min = a.r + c.r
        if (dist < min) {
          let nx = dist == 0 ? 1 : dx / dist
          let ny = dist == 0 ? 0 : dy / dist
          let push = (min - dist) / 2
          a.x -= nx * push
          a.y -= ny * push
          c.x += nx * push
          c.y += ny * push
          a.x = Math.min(Math.max(a.x, a.r), 400 - a.r)
          a.y = Math.min(Math.max(a.y, a.r), 300 - a.r)
          c.x = Math.min(Math.max(c.x, c.r), 400 - c.r)
          c.y = Math.min(Math.max(c.y, c.r), 300 - c.r)
          let tx = a.vx
          let ty = a.vy
          a.vx = c.vx
          a.vy = c.vy
          c.vx = tx
          c.vy = ty
        }
      }
    }
  }

  fn draw() {
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#e11d48"
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn tick() {
    if (!paused) {
      step()
      draw()
      frames++
    }
    raf = requestAnimationFrame(tick)
  }

  fn addBall() {
    balls.push(makeBall())
    count = balls.length
  }

  fn togglePause() {
    paused = !paused
  }

  fn reset() {
    balls = makeBalls(5)
    count = 5
    frames = 0
    draw()
  }

  mount {
    ctx = box.getContext("2d")
    balls = makeBalls(5)
    count = 5
    raf = requestAnimationFrame(tick)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" primary -> addBall()
      button `${paused ? "Reanudar" : "Pausar"}` -> togglePause()
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

files.format.art:
fn formatDate(iso) {
  const [y, m, d] = iso.split("-")
  return `${d}/${m}/${y}`
}

fn formatUSD(n) {
  return "US$ " + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ".")
}

fn initials(name) {
  return name.split(" ").filter(w => w.length > 0).slice(0, 2).map(w => w[0]).join("").toUpperCase()
}

fn avatarColor(name) {
  let h = 0
  for (let i = 0; i < name.length; i++) {
    h = (h * 31 + name.charCodeAt(i)) % 360
  }
  return `hsl(${h}, 55%, 45%)`
}

fn avatarStyle(name) {
  return `background:${avatarColor(name)};color:#fff;width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:600;flex-shrink:0`
}

