use "./data.art" { TRAVELERS, COUNTRY_OPTIONS }
use "./format.art" { formatDate, formatUSD, initials, avatarStyle }

page Home "/" {
  meta title="Viajeros"
  state country = "Todos"
  computed visible = TRAVELERS
    .filter(t => country == "Todos" || t.country == country)
    .slice()
    .sort((a, b) => a.arrival < b.arrival ? -1 : a.arrival > b.arrival ? 1 : 0)

  column gap=4 pad=4 {
    title "Viajeros" tag=h1
    text `${visible.length} viajeros`
    select country options=COUNTRY_OPTIONS label="País"
    column gap=3 {
      for t in visible key t.id {
        card {
          row gap=3 align=center {
            row style=(avatarStyle(t.name)) {
              text initials(t.name)
            }
            column gap=1 {
              link t.name to=(`/viajero/${t.id}`)
              text `${t.city}, ${t.country}` muted
              text `Llega el ${formatDate(t.arrival)}` small
              text formatUSD(t.budget)
            }
          }
        }
      }
    }
  }
}

page Traveler "/viajero/:id" {
  computed t = TRAVELERS.find(x => String(x.id) == params.id)

  column gap=3 pad=4 {
    if t {
      title t.name tag=h1
      text `${t.city}, ${t.country}`
      text `Llega el ${formatDate(t.arrival)}`
      text `Presupuesto: ${formatUSD(t.budget)}`
    } else {
      text "Viajero no encontrado"
    }
    link "Volver" to="/"
  }
}

